gv9(){return"\u0641\u064a 21:00 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u063a\u062f \u0641\u064a\u0647 \u062a\u0645\u0627\u0631\u064a\u0646."},
gv6(){return"\u0645\u0646\u0628\u0647 \u0627\u0644\u062a\u0645\u0631\u064a\u0646"},
gv7(){return"\u0625\u0634\u0627\u0631\u0629 \u0642\u0628\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0628\u0642\u0644\u064a\u0644\u060c \u0625\u0630\u0627 \u0641\u0639\u0651\u0644\u062a\u0647\u0627."},
